test('a later failed request cannot be overwritten by an older successful response',async()=>{
 const nodes={'outcome-root':{innerHTML:'',style:{}},'outcome-gate':{style:{}}};
 const document={getElementById:id=>nodes[id]};let finish;
 const older=R.load('old',{document,fetch:()=>new Promise(resolve=>{finish=resolve;})});
 await R.load('new',{document,fetch:async()=>({status:401,ok:false})});
 finish({status:200,ok:true,json:async()=>sample()});await older;
 assert.match(nodes['outcome-root'].innerHTML,/not recognized/);assert.doesNotMatch(nodes['outcome-root'].innerHTML,/oc-row/);
});

test('clear report removes loaded data and reopens the gate without token storage',async()=>{
 const dom=fakeDom();const window={document:dom.document,fetch:async()=>({status:200,ok:true,json:async()=>sample()})};
 vm.runInContext(SRC,vm.createContext({window,Promise,Date,isFinite,isNaN,String,Array,Error}));
 dom.byId.get('outcome-token').value='TOKEN-VALUE';await dom.byId.get('outcome-unlock').listeners.click[0]();
 dom.byId.get('outcome-clear').listeners.click[0]();
 assert.equal(dom.byId.get('outcome-root').innerHTML,'');assert.equal(dom.byId.get('outcome-token').value,'');assert.equal(dom.byId.get('outcome-gate').style.display,'');
});
